+/**
+ * Checks whether the host portion of a URL belongs to a trusted Firebase
+ * authentication domain. This is used to ensure that URLs supplied via
+ * user-controlled configuration (e.g. the FIREBASE_DEFAULTS cookie) cannot
+ * cause requests containing session identifiers to be sent to attacker
+ * controlled servers.
+ *
+ * @param host  The host portion of the URL to validate.
+ * @param authDomain  The auth domain configured for the Firebase app.
+ */
+export function isValidHost(host: string, authDomain: string): boolean {
+  if (!host || !authDomain) {
+    return false;
+  }
+  const normalizedHost = host.toLowerCase();
+  const normalizedDomain = authDomain.toLowerCase();
+  if (normalizedHost === normalizedDomain) {
+    return true;
+  }
+  // Allow subdomains of the auth domain (e.g. project.firebaseapp.com).
+  if (normalizedHost.endsWith(`.${normalizedDomain}`)) {
+    return true;
+  }
+  return false;
+}

