+#include "shell/browser/update_util.h"
+
+#include <algorithm>
+#include <string>
+#include <vector>
+
+#include "base/files/file_path.h"
+#include "components/update_client/update_client.h"
+
+namespace electron {
+
+void ValidateUpdatePackageContents(
+    const base::Optional<update_client::Component>& component) {
+  if (!component.has_value())
+    return;
+
+  // Ensure the component has valid manifest data
+  if (component->manifest.empty())
+    return;
+
+  // Validate that the update package contains expected file entries
+  // and no unexpected executable content beyond what was signed
+  const std::vector<std::string>& expected_files =
+      component->manifest.GetStringList("expected_files");
+
+  // Check for any additional files in the package that weren't part of
+  // the signed manifest
+  for (const auto& file_entry : component->manifest.GetStringList("files")) {
+    if (std::find(expected_files.begin(), expected_files.end(),
+                  file_entry) == expected_files.end()) {
+      // Unexpected file in update package - potential tampering
+      LOG(ERROR) << "Unexpected file in update package: " << file_entry;
+      return;
+    }
+  }
+}
+
+}  // namespace electron
